import styled from '@emotion/styled';

import { theme } from '../../../theme';

export const StyledPageContainer = styled.div({
  alignItems: 'center',
  display: 'flex',
  flexDirection: 'column',
  height: 'auto',
  width: '20.625rem',
});

export const StyledOnlyActionContainer = styled.div({
  alignItems: 'center',
  display: 'flex',
});

export const StyledTwoActionsContainer = styled.div({
  display: 'flex',
  gap: theme.spacing['4'],
  justifyContent: 'center',
  width: '20.625rem',
});

export const StyledPageTitle = styled.h2({
  fontFamily: theme.fonts.heading,
  fontSize: theme.fonts.fontSizes['7'],
  fontWeight: theme.fonts.fontWeights.semibold,
  lineHeight: theme.fonts.lineHeights['8'],
  margin: 0,
  padding: theme.spacing['2'],
  textAlign: 'center',
  width: '18.75rem',
});

export const StyledPageDescription = styled.p({
  fontFamily: theme.fonts.paragraph,
  fontSize: theme.fonts.fontSizes['3'],
  fontWeight: theme.fonts.fontWeights.normal,
  height: theme.spacing['3'],
  lineHeight: theme.fonts.lineHeights['6'],
  margin: 0,
  overflow: 'hidden',
  paddingBottom: theme.spacing['6'],
  textAlign: 'center',
  width: '18.75rem',
  wordWrap: 'break-word',
});

export const StyledSectionContainer = styled.div({
  alignItems: 'center',
  display: 'flex',
  flexDirection: 'column',
  height: 'auto',
  width: '11.25rem',

  img: {
    height: '8.25rem',
    width: '8.25rem',
  },
});

export const StyledSectionDescription = styled.p({
  color: theme.colors.interfaceLabelSecondary,
  fontFamily: theme.fonts.paragraph,
  fontSize: theme.fonts.fontSizes['2'],
  fontWeight: theme.fonts.fontWeights.normal,
  height: 'auto',
  lineHeight: theme.fonts.lineHeights['3'],
  margin: 0,
  paddingTop: theme.spacing['4'],
  textAlign: 'center',
  width: '11rem',
});
